let fleetView='cards',commandStrategy='balanced',labPreset='base';
const routeSymbols=['↗','◷','≈','⇄','✳','＋'];
const routeColors=['clay','sand','sage','sage','ink','clay'];
function boardArt(a,large=false){return `<div class="board-art ${large?'large':''}" aria-hidden="true"><div class="board-pins"></div><div class="board-plate"><span class="board-code">RE / ${a.id.slice(-3)}</span><div class="board-vents"></div><div class="board-chip">Re<span>↗</span></div><span class="board-model">${a.model.replace('NVIDIA ','')}</span></div></div>`}
function sceneLabel(n,label){return `<div class="scene-label"><span>${n}</span>${label}</div>`}
heading=function(title,sub,action=''){return `<div class="pagehead"><div>${sceneLabel('RE:',navs.find(n=>n[0]===page)?.[2]||'DECISION STUDIO')}<h1>${title}</h1><p>${sub}</p></div>${action}</div>`};
function strip(){return `<div class="studio-context"><span><i></i> YOUR DEMO FLEET</span><span>08 assets</span><span>03 locations</span><span>Illustrative intelligence · saved on this device</span></div>`}
function journey(){return `<div class="journey-strip">${[['fleet','01','Understand your assets','Open a passport'],['lab','02','Explore the possibilities','Compare the economics'],['command','03','Make your move','Build an action plan'],['outcomes','04','See what happened','Track the outcome']].map(x=>`<a href="#${x[0]}"><span>${x[1]}</span><div><b>${x[2]}</b><small>${x[3]} ↗</small></div></a>`).join('')}</div>`}
function routeValue(a,r=a.route){let v=calculate(a);return [v.sale,v.wait,v.host,v.hybrid,v.harvest,v.repair][r]}
overview=function(){const a=assets[4],v=calculate(a);return strip()+heading('Good hardware.<br><em>Better next moves.</em>','Start with one decision. See the whole fleet differently.',`<a href="#fleet" class="btn secondary">Meet your fleet <span>↗</span></a>`)+`<div class="studio-overview"><section class="feature-decision"><div class="feature-top"><span class="micro">THE NEXT WORTHWHILE MOVE</span><span class="pill">01 / 03 opportunities</span></div><div class="feature-content"><div><span class="route-eyebrow">${routeSymbols[5]} REPAIR / RECOVER VALUE</span><h2>A small repair.<br><em>A longer story.</em></h2><p>Your A100’s cooling fault is serviceable in this demo. A $380 repair could recover ${money(v.repair-v.sale)} more than selling it as-is.</p><button class="btn" data-passport="${a.id}">See the thinking <span>↗</span></button></div><div class="asset-stage">${boardArt(a,true)}<div class="asset-stage-caption"><span>RC-005 / NVIDIA A100</span><b>40 GB · Phoenix</b></div></div></div><div class="decision-bottom"><span><i></i> Demo diagnostic: cooling service</span><span>Repair quote needs verification</span></div></section><section class="fleet-snapshot"><span class="micro">THE BIG PICTURE</span><div class="snapshot-total"><small>Estimated fleet resale</small><strong>${money(total)}</strong><span>Before fees · 8 illustrative assets</span></div><div class="fleet-health-art"><div class="health-circle"><span>84<small>/ 100</small></span></div><div><b>Plenty of life left.</b><p>6 healthy assets.<br>2 need a closer look.</p></div></div><div class="snapshot-bottom"><a href="#outcomes"><strong>${saved.plans.filter(p=>!p.done).length.toString().padStart(2,'0')}</strong><span>decisions in motion ↗</span></a><a href="#lab"><strong>${money(assets.reduce((s,a)=>s+calculate(a).net,0))}</strong><span>90-day hosting potential ↗</span></a></div></section></div><div class="sectiontitle"><div><span class="micro">WHERE POSSIBILITY BECOMES A PLAN</span><h2>Your next chapter, in four moves.</h2></div><a href="#home" class="textlink">Revisit the guided demo ↗</a></div>${journey()}<div class="sectiontitle"><h2>Two more possibilities worth a look.</h2><a href="#market" class="textlink">Open Opportunity Radar ↗</a></div><div class="opportunity-pair">${[[assets[0],'Earn before the handover.','Your H100 can keep working while you look for its next owner.'],[assets[1],'Timing is part of the value.','Compare immediate liquidity against another quarter of hosting.']].map(([a,t,p])=>`<button class="opportunity-tile" data-passport="${a.id}"><span class="tile-symbol">${routeSymbols[a.route]}</span><div><small>${a.id} / ${a.model}</small><h3>${t}</h3><p>${p}</p></div><span>↗</span></button>`).join('')}</div>`};
function assetCard(a){return `<article class="asset-card ${routeColors[a.route]}"><div class="asset-card-top"><span>${a.id}</span><span><i class="health-dot ${a.health<70?'needs':''}"></i>${a.health<70?'Needs attention':'Ready for what’s next'}</span></div><button class="asset-visual" data-passport="${a.id}" aria-label="Open passport ${a.id}">${boardArt(a)}</button><div class="asset-card-copy"><small>${a.site}</small><h2>${a.model.replace('NVIDIA ','')}<span>NVIDIA</span></h2><p>${a.memory} <span>·</span> ${a.age} months in service</p><div class="asset-card-stats"><div><span>Est. resale</span><strong>${money(a.value)}</strong></div><div><span>Health</span><strong>${a.health}<small>/100</small></strong></div></div><button class="asset-route" data-passport="${a.id}"><span>${routeSymbols[a.route]} &nbsp; ${routes[a.route]}</span><span>Open passport ↗</span></button></div></article>`}
fleet=function(){let list=assets.filter(a=>(a.model+' '+a.id+' '+a.site).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||a.route===+filter));return heading('Every asset has<br><em>a story worth knowing.</em>','Open a passport to understand the hardware—and its next best chapter.',`<button class="btn secondary" id="export">Export inventory ↓</button>`)+`<div class="fleet-controls"><div class="toolbar"><input type="search" id="search" aria-label="Search fleet" placeholder="Find an asset, model, or location…" value="${esc(query)}"><select id="filter" aria-label="Filter by recommendation"><option value="all">All next chapters</option>${routes.map((r,i)=>`<option value="${i}" ${filter==i?'selected':''}>${r}</option>`).join('')}</select></div><div class="view-switch" aria-label="Fleet view"><button data-view="cards" aria-pressed="${fleetView==='cards'}">▦ Cards</button><button data-view="list" aria-pressed="${fleetView==='list'}">☷ List</button></div></div><div class="collection-caption"><span>${String(list.length).padStart(2,'0')} ASSETS IN VIEW</span><span>Illustrative valuations · USD</span></div>${fleetView==='cards'?`<div class="asset-gallery">${list.map(assetCard).join('')||'<div class="empty">No assets found. Try another model or clear the filter.</div>'}</div>`:table(list)}<div class="collection-note"><span>↗</span><p>A passport travels with the asset.<br><small>Condition, economics, and the next move—all in one place.</small></p><a href="#command" class="textlink">Think across the whole fleet ↗</a></div>`};
function strategyRoute(a){if(commandStrategy==='liquidity')return a.health<50?4:0;if(commandStrategy==='earning')return a.health<50?4:a.health<70?5:2;return a.route}
command=function(){let chosen=assets.filter(a=>selected.has(a.id));return heading('Many assets.<br><em>One considered plan.</em>','Choose your priority. Review each route. Then put the decisions in motion.')+`<div class="strategy-bar"><div><span class="micro">WHAT MATTERS MOST RIGHT NOW?</span><div class="strategy-options">${[['balanced','A balanced next chapter'],['liquidity','Free up capital'],['earning','Keep earning']].map(([k,v])=>`<button data-strategy="${k}" aria-pressed="${commandStrategy===k}">${v}</button>`).join('')}</div></div><button class="textlink" id="toggleAll">${chosen.length===assets.length?'Deselect all':'Select all'}</button></div><div class="command-workspace"><div class="command-board">${[['Earn', [2,3]],['Exit',[0,1]],['Recover',[4,5]]].map(([label,rs])=>{let list=assets.filter(a=>rs.includes(strategyRoute(a)));return `<section class="command-lane"><div class="lane-title"><h2>${label}</h2><span>${list.length.toString().padStart(2,'0')}</span></div>${list.map(a=>`<label class="command-asset ${selected.has(a.id)?'selected':''}"><div class="row"><span class="micro">${a.id}</span><input type="checkbox" data-select="${a.id}" aria-label="Select ${a.id}" ${selected.has(a.id)?'checked':''}></div><h3>${a.model.replace('NVIDIA ','')}</h3><p>${a.memory}</p><div class="row"><span>${routeSymbols[strategyRoute(a)]} ${routes[strategyRoute(a)]}</span><b>${money(routeValue(a,strategyRoute(a)))}</b></div></label>`).join('')||'<p class="lane-empty">No assets on this route.</p>'}</section>`}).join('')}</div><aside class="plan-summary"><span class="micro">YOUR PROPOSED NEXT CHAPTER</span><h2>${chosen.length}<em> ${chosen.length===1?'asset':'assets'}.</em><br>One clear direction.</h2><div class="plan-value"><span>Combined route value</span><strong>${money(chosen.reduce((s,a)=>s+routeValue(a,strategyRoute(a)),0))}</strong><small>Net estimates at each route’s modeled exit</small></div><p>Each selected asset gets a decision in your ledger. Review and record the actual outcome as work progresses.</p><button class="btn" id="studioCreatePlan" ${chosen.length?'':'disabled'}>Save ${chosen.length} ${chosen.length===1?'decision':'decisions'} <span>↗</span></button><small>Planning only. No transactions are initiated.</small></aside></div><details class="model-details"><summary>How this plan is calculated</summary><p>Balanced uses the demo recommendations. Capital prioritizes immediate sale except parts recovery for health below 50. Earning selects hosting for healthy assets and recovery for others. Values combine immediate exits, 45-day sales, 90-day hosting exits, and modeled repair or harvest proceeds. This sum is not a same-date portfolio valuation. Hosting assumes 70% utilization, $0.12/kWh and 3% monthly depreciation.</p></details>`};
lab=function(){labPreset='base';return heading('A little curiosity.<br><em>A clearer decision.</em>','Play out the possibilities before you commit. Every assumption is yours to change.')+`<div class="lab-presets"><span class="micro">START WITH A POSSIBILITY</span>${[['base','Business as usual'],['demand','What if demand rises?'],['cost','What if power gets expensive?']].map(([k,v])=>`<button data-preset="${k}" aria-pressed="${labPreset===k}">${v}</button>`).join('')}</div><div class="labgrid studio-lab"><section class="lab-controls"><span class="micro">THE INPUTS / YOUR CALL</span><label for="labasset">Choose your asset</label><select id="labasset">${assets.map(a=>`<option value="${a.id}" ${a.id===focusAsset.id?'selected':''}>${a.model.replace('NVIDIA ','')} · ${a.id}</option>`).join('')}</select>${slider('util','Utilization',70,10,100,1,'%')}${slider('energy','Electricity',.12,.04,.4,.01,' / kWh')}${slider('days','Time horizon',90,30,365,1,' days')}${slider('decline','Monthly depreciation',3,0,12,.5,'%')}<button class="btn" id="saveScenario">Keep this comparison +</button><details class="model-details"><summary>Fees & model assumptions</summary><p>12% hosting fee, 5% sale fee, idle power at 35% of rated draw. Compounded monthly depreciation. Excludes downtime, tax, financing, and discounting. Illustrative inputs.</p></details></section><section class="lab-output"><div id="labresults" aria-live="polite"></div><section class="saved-comparisons"><div class="panelhead"><h2>Your saved possibilities</h2><small>ON THIS DEVICE</small></div><div id="comparisons"></div></section></section></div>`};
updateLab=function(){for(const id of ['util','energy','days','decline'])$('#'+id+'Value').textContent=(id==='energy'?'$':'')+$('#'+id).value+$('#'+id).dataset.suffix;let v=getLab(),days=+$('#days').value;let options=[['Sell now',v.sale,'Liquidity today.'],['Host longer',v.host,'Income, then exit.'],['Yield while listed',v.hybrid,'Earn until a halfway sale.'],['List and wait',v.wait,'Wait for a 3.5% premium.']].sort((a,b)=>b[1]-a[1]);let values=Array.from({length:13},(_,i)=>calculate(focusAsset,+$('#util').value,+$('#energy').value,days*i/12,+$('#decline').value).host),min=Math.min(...values,v.sale)*.95,max=Math.max(...values,v.sale)*1.03,y=n=>175-(n-min)/(max-min)*135;let pts=values.map((n,i)=>`${35+i*46},${y(n)}`).join(' ');$('#labresults').innerHTML=`<div class="lab-verdict"><div><span class="micro">LEADING IN THIS MODEL</span><h2>${options[0][0]}<span>↗</span></h2><p>${money(options[0][1]-v.sale)} ${options[0][1]>=v.sale?'more':'less'} than selling today at these assumptions.</p></div><div><strong>${money(options[0][1])}</strong><small>estimated net value</small></div></div>${focusAsset.health<70?'<div class="model-health-note">This asset needs service. Hosting projections assume operational hardware and exclude repair costs.</div>':''}<div class="trajectory"><div class="row"><span class="micro">HOW THE FUTURE ADDS UP</span><span class="chart-key"><i></i> Host + resale <b></b> Sell today</span></div><svg viewBox="0 0 620 210" role="img" aria-label="Projected hosting and resale value over ${days} days compared with selling today"><path d="M35 40H590 M35 105H590 M35 175H590" stroke="#dddcd1" stroke-dasharray="3 6"/><polygon points="35,180 ${pts} 587,180" fill="#e4e9d7"/><path d="M35 ${y(v.sale)}H590" stroke="#bf7659" stroke-dasharray="6 5" stroke-width="2"/><polyline points="${pts}" fill="none" stroke="#546b49" stroke-width="3"/><circle cx="587" cy="${y(values[12])}" r="5" fill="#546b49"/><text x="35" y="203">Today</text><text x="270" y="203">Day ${Math.round(days/2)}</text><text x="540" y="203">Day ${days}</text></svg></div><div class="route-comparison">${options.map((o,i)=>`<div class="route-option ${i===0?'leading':''}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${o[0]}</h3><small>${o[2]}</small></div><strong>${money(o[1])}</strong></div>`).join('')}</div><div class="economic-equation"><span><b>${money(v.revenue)}</b>hosting revenue</span><i>−</i><span><b>${money(v.power+v.fees)}</b>power & fees</span><i>+</i><span><b>${money(v.residual*.95)}</b>net exit value</span><i>=</i><span><b>${money(v.host)}</b>host + sell</span></div>`;renderComparisons()};
market=function(){return heading('A moving market.<br><em>A moment to act.</em>','Signals become useful when they connect to hardware you actually own.')+`<div class="radar-layout"><section class="radar-visual"><span class="micro">OPPORTUNITY RADAR / DEMO SIGNALS</span><div class="radar-map"><div class="radar-ring r1"></div><div class="radar-ring r2"></div><div class="radar-ring r3"></div><span class="radar-center">Re.</span><button class="radar-node n1" data-passport="RC-001" aria-label="Inspect H100 earning signal">01<span>Earn</span></button><button class="radar-node n2" data-passport="RC-002" aria-label="Inspect A100 exit signal">02<span>Exit</span></button><button class="radar-node n3" data-passport="RC-005" aria-label="Inspect A100 repair signal">03<span>Recover</span></button></div><h2>Three signals.<br><em>Your next move?</em></h2><p>Explore a signal to see the asset, the assumptions, and the trade-off.</p></section><div class="signal-editorial">${[[assets[0],'01','Opportunity to earn','Idle doesn’t have to mean unproductive.','Assumed rental demand supports hosting while this healthy H100 waits for a buyer.','Demand index','118 / baseline 100'],[assets[1],'02','A timing question','The cost of waiting is worth a look.','An illustrative 3.2% decline in the A100 resale index makes the holding period a decision worth modeling.','A100 resale index','96.8 / −3.2%'],[assets[4],'03','A recovery opportunity','One repair could rewrite the outcome.','A cooling service is modeled at $380. Check a real quote before choosing a repair-led exit.','Modeled uplift','24% before repair cost']].map(([a,n,k,t,p,m,v])=>`<article class="signal-story"><span class="signal-number">${n}</span><div><span class="micro">${k}</span><h2>${t}</h2><p>${p}</p><div class="signal-evidence"><span>${m}</span><b>${v}</b></div><button class="textlink" data-passport="${a.id}">Explore ${a.model.replace('NVIDIA ','')} · ${a.id} ↗</button></div></article>`).join('')}</div></div><p class="studio-footnote">Curated demo signals, not live pricing or alerts. Your backend will supply market intelligence after integration.</p>`};
outcomes=function(){let done=saved.plans.filter(p=>p.done),actual=done.reduce((s,p)=>s+p.actual,0),expected=done.reduce((s,p)=>s+p.expected,0);return heading('Every next chapter.<br><em>Accounted for.</em>','A decision is a beginning. The outcome tells you what to learn.',`<a class="btn secondary" href="#command">Build a new plan ↗</a>`)+`<div class="outcome-score"><div><span class="micro">REALIZED VALUE</span><strong>${money(actual)}</strong><p>${done.length} completed ${done.length===1?'decision':'decisions'}</p></div><div><span class="micro">AGAINST YOUR PLAN</span><strong>${actual-expected>=0?'+':''}${money(actual-expected)}</strong><p>Variance on completed decisions only</p></div><div class="score-story"><span>↗</span><p>The more you close the loop,<br><em>the clearer the next move.</em></p></div></div><div class="ledger-board">${[[false,'In motion','The next chapters you’ve chosen.'],[true,'Realized','What actually happened.']].map(([complete,title,sub])=>`<section class="ledger-lane"><div class="lane-title"><div><h2>${title}</h2><p>${sub}</p></div><span>${saved.plans.filter(p=>p.done===complete).length}</span></div>${saved.plans.map((p,i)=>({p,i})).filter(({p})=>p.done===complete).map(({p,i})=>`<article class="ledger-card"><div class="row"><span class="micro">${esc(p.id)} / ${esc(p.date)}</span><span class="pill">${p.done?'Completed':'Planned'}</span></div><h3>${esc(p.model)}</h3><p>${esc(p.route)}</p><div class="ledger-value"><span>${p.done?'Realized net value':'Expected route value'}</span><strong>${money(p.done?p.actual:p.expected)}</strong></div>${p.done?`<p class="ledger-variance">${p.actual-p.expected>=0?'+':''}${money(p.actual-p.expected)} against the original plan</p>`:`<button class="btn secondary" data-complete="${i}">Record what happened ↗</button>`}<button class="ledger-remove" data-remove-plan="${i}" aria-label="Remove decision ${i+1}">Remove</button></article>`).join('')||`<div class="ledger-empty"><span>${complete?'◎':'↗'}</span><h3>${complete?'The story is still unfolding.':'Room for your next move.'}</h3><p>${complete?'Record a completed outcome to see the value here.':'Open an asset passport or build a fleet plan to get started.'}</p>${complete?'':'<a href="#fleet" class="textlink">Meet your fleet ↗</a>'}</div>`}</section>`).join('')}</div>`};
passport=function(id){let a=assets.find(a=>a.id===id);focusAsset=a;let v=calculate(a);$('#passport').className='passport-dialog';$('#passport').setAttribute('aria-label',a.model+' asset passport');$('#passport').innerHTML=`<div class="passport-layout"><section class="passport-cover"><div class="row"><a class="studio-wordmark" href="#home" data-close-link>ReCompute®</a><span class="micro">ASSET / ${a.id}</span></div><div class="passport-object">${boardArt(a,true)}</div><span class="micro">THE ASSET PASSPORT</span><h2>${a.model.replace('NVIDIA ','')}</h2><p>${a.memory}</p><div class="passport-cover-bottom"><span>${a.site}</span><span>${a.age} months in service</span></div></section><section class="passport-reading"><div class="row"><span class="micro">UNDERSTAND → DECIDE → ACT</span><button class="close" data-close aria-label="Close passport">×</button></div><p class="passport-mobile-identity">${a.model} · ${a.id} · ${a.memory}</p><h2>${a.health<70?'A little attention.<br><em>A different future.</em>':'Good condition.<br><em>Open possibilities.</em>'}</h2><div class="passport-health"><strong>${a.health}<small>/100</small></strong><div><b>${a.health>90?'Excellent condition':a.health>70?'Good condition':'Service required'}</b><p>Illustrative diagnostic score</p></div><div class="health-meter"><i style="width:${a.health}%"></i></div></div><div class="passport-facts"><div><span>Estimated resale</span><b>${money(a.value)}</b></div><div><span>Rated power</span><b>${a.watts} W</b></div><div><span>Service assessment</span><b>${a.health<50?'Parts recovery':a.health<70?'Cooling service':'No repair indicated'}</b></div><div><span>Before a transfer</span><b>Data wipe required</b></div></div><div class="passport-recommendation"><span class="micro">A POSSIBLE NEXT CHAPTER</span><div class="row"><h3>${routes[a.route]}</h3><span>${routeSymbols[a.route]}</span></div><p>${['Turn today’s resale value into available capital. Compare against the income you’d give up by exiting now.','A 3.5% asking premium is modeled. Patience only helps when the premium exceeds depreciation.','Good condition supports another workload. Utilization and energy costs determine whether it pays.','Earn while looking for the next owner. The demo assumes a sale after 45 days.','Recover component value from hardware with limited remaining useful life. Obtain a parts quote first.','The model assumes $380 in service costs and a 24% resale uplift. Confirm a quote and post-repair diagnostics.'][a.route]}</p><div class="recommendation-value"><span>Modeled net route value</span><strong>${money(routeValue(a))}</strong></div></div><details class="model-details"><summary>See the economics behind the recommendation</summary><div class="economics"><p>Sell now <b>${money(v.sale)}</b></p><p>90-day hosting + exit <b>${money(v.host)}</b></p><p>Service + sell <b>${money(v.repair)}</b></p><p>Harvest <b>${money(v.harvest)}</b></p></div><p>70% utilization · $0.12/kWh · 3% monthly depreciation · 12% hosting and 5% selling fees. Estimates are uncertain, not quotes.</p></details><label for="routeSelect" class="route-label">Your choice</label><select id="routeSelect">${routes.map((r,i)=>`<option value="${i}" ${i===a.route?'selected':''}>${r}</option>`).join('')}</select><div class="modalactions"><button class="btn secondary" id="passportLab">Explore what-if ↗</button><button class="btn" id="planAsset">Save this decision +</button></div></section></div>`;$('#passport').showModal()};
about=function(){return heading('Value isn’t finished.<br><em>It’s waiting to be redirected.</em>','ReCompute brings a longer view to the life of compute.')+`<section class="about-statement"><span>Re.</span><div><h2>Built for the moment<br>between <em>what was</em><br>and <em>what’s next.</em></h2><p>Hardware outlives workloads. We believe its next chapter deserves the same care as its first: clear evidence, thoughtful economics, and a decision you can explain.</p></div></section>${journey()}<section class="about-principles">${[['01','Understand before acting.','A passport connects condition, history, security, and valuation.'],['02','Make the trade-off visible.','Explore assumptions. Compare routes. Keep control of the decision.'],['03','Learn from the next chapter.','Record what happened and compare it with what you expected.']].map(x=>`<div><span class="micro">${x[0]} / OUR APPROACH</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</section><p class="studio-footnote">A design prototype with illustrative data and browser-local planning. Live AI, telemetry, markets, and shared persistence await your backend integration.</p>`};
// Extend existing event handlers without replacing the tested persistence paths.
document.addEventListener('click',e=>{let t=e.target.closest('button');if(e.target.closest('[data-close-link]'))$('#passport').close();if(!t)return;if(t.dataset.view){fleetView=t.dataset.view;render()}if(t.dataset.strategy){commandStrategy=t.dataset.strategy;render()}if(t.id==='studioCreatePlan'){let count=0;assets.filter(a=>selected.has(a.id)).forEach(a=>{if(addPlan(a,strategyRoute(a)))count++});location.hash='outcomes';toast(`${count} ${count===1?'decision':'decisions'} saved. Your plan is ready to follow.`)}if(t.dataset.preset){labPreset=t.dataset.preset;$('#util').value=labPreset==='demand'?90:70;$('#energy').value=labPreset==='cost'?.3:.12;document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.preset===labPreset));updateLab()}if(t.dataset.complete!==undefined||t.id==='reset')$('#passport').className=''});
let previewMode='understand';
function studioBridgePreview(){let a=assets[1];const p={understand:['01 / UNDERSTAND','A whole asset.\nA clearer picture.','Explore the fleet','#fleet'],explore:['02 / EXPLORE','What changes\nwhen you change the inputs?','Open the What-if Lab','#lab'],act:['03 / ACT','A considered decision.\nA plan you can follow.','Build a fleet plan','#command']}[previewMode];return `<div class="bridge-copy"><span class="micro">${p[0]}</span><h3>${p[1].replace('\n','<br>')}</h3><p>${previewMode==='understand'?'See beyond a model number. Health, history, valuation, and security belong together.':previewMode==='explore'?'Try different demand, energy costs, and timelines. See the economics change before you commit.':'Choose your priority and review a route for every asset. Track what happens after the decision.'}</p><a class="btn" href="${p[3]}">${p[2]} ↗</a></div><div class="bridge-object">${previewMode==='understand'?`<div class="mini-passport"><div class="row"><span class="micro">ASSET PASSPORT</span><span class="micro">RC-002</span></div>${boardArt(a)}<h4>A100 <small>80 GB</small></h4><div class="row"><span>94 / 100 health</span><b>$11,200</b></div><div class="mini-status">● Ready for its next chapter</div></div>`:previewMode==='explore'?`<div class="mini-scenario"><span class="micro">ONE ASSET. DIFFERENT FUTURES.</span><h4>What if <em>it keeps earning?</em></h4><div class="mini-plot"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="row"><span>Sell now</span><b>${money(calculate(a).sale)}</b></div><div class="row"><span>Host + sell</span><b>${money(calculate(a).host)}</b></div><small>Illustrative 90-day comparison</small></div>`:`<div class="mini-plan"><span class="micro">A PLAN WITH A PURPOSE</span>${[['H100','Earn','⇄'],['A100','Exit','↗'],['V100','Recover','✳']].map(x=>`<div><span>${x[2]}</span><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}<p>One fleet. Several new beginnings.</p></div>`}</div>`}
function studioBridge(){return `<section class="studio-bridge"><div class="bridge-heading"><div><span class="section-index">THE EXPERIENCE DOESN’T END AT THE DEMO</span><h2>Curiosity, meet<br><em>your decision studio.</em></h2></div><p>A place to understand, explore, and act.<br>Built around the next move—not just the numbers.</p></div><div class="bridge-tabs">${[['understand','Understand the asset'],['explore','Explore the possibilities'],['act','Make a plan']].map(([k,t])=>`<button data-bridge="${k}" aria-pressed="${previewMode===k}">${t}</button>`).join('')}</div><div id="bridge-preview" class="bridge-preview">${studioBridgePreview()}</div></section>`}
const narrativeExperience=experience;
experience=function(){return narrativeExperience().replace('<section class="possibilities">',studioBridge()+'<section class="possibilities">').replace('Enter workspace ↗','Enter the studio ↗').replace('Explore the demo workspace','Explore the Decision Studio')};
document.addEventListener('click',e=>{let t=e.target.closest('[data-bridge]');if(t){previewMode=t.dataset.bridge;document.querySelectorAll('[data-bridge]').forEach(b=>b.setAttribute('aria-pressed',b===t));$('#bridge-preview').innerHTML=studioBridgePreview()}});
render();
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.removePlan!==undefined&&window.lastRemoved){window.lastRemovedIndex=+t.dataset.removePlan;clearTimeout(window.toastTimer);$('#toast').innerHTML='Decision removed. <button id="undoDecision">Undo</button>';$('#toast').classList.add('show');window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),8000)}if(t.id==='undoDecision'&&window.lastRemoved){saved.plans.splice(window.lastRemovedIndex,0,window.lastRemoved);window.lastRemoved=null;persist();render();toast('Decision restored.')}});
